/** Secret object with optional id.*/
type PasswordSecret = Readonly<{
  id?: string | undefined;
  secret: Password;
}>;

/** Secret object with optional id and specified password for each encryption and integrity. */
type PasswordSpecific = Readonly<{
  id?: string | undefined;
  encryption: Password;
  integrity: Password;
